// Derived top-25 words per kanji — sourced from data/kanji-words.json,
// which is generated by tools/build-kanji-words.py from JMdict.
// Exposed as window.loadKanjiWords(). Keyed by card idx (string).

async function loadKanjiWords() {
  const res = await fetch('data/kanji-words.json');
  return res.json();
}

window.loadKanjiWords = loadKanjiWords;
